// Generated by Cypress Author on 2026-10-19
//
// AUT 06 · REL 07 (P0) — Plano_de_Testes_QA_MatchWallet.md §3 e §8.
// Isolamento entre clientes: o cliente A usa identificadores do cliente B e nada pode vazar nem
// mudar. Requer DOIS clientes em cypress.env.json (`cliente*` e `cliente2*`); relatório de B é
// opcional — sem ele o teste de download fica pulado (Bloqueado por massa), nunca "aprovado".

const NEGADO = [401, 403, 404]

describe('Plano QA · Isolamento entre clientes', () => {
  it('AUT 06 · cliente A usa o id do cliente B → leituras e alterações negadas', () => {
    cy.loginReal('cliente2')
    cy.apiRequest<{ id: string }>({ method: 'GET', url: '/auth/me' }).its('body.id').as('idB')

    cy.loginReal('cliente')
    cy.get<string>('@idB').then((idB) => {
      cy.apiRequest({
        method: 'GET',
        url: `/usuarios/${idB}/historico-suitability`,
        failOnStatusCode: false,
      })
        .its('status')
        .should('be.oneOf', NEGADO)

      cy.apiRequest({
        method: 'PATCH',
        url: `/usuarios/${idB}`,
        body: { ativo: false },
        failOnStatusCode: false,
      })
        .its('status')
        .should('be.oneOf', NEGADO)
    })

    // B continua ativo e íntegro.
    cy.loginReal('cliente2')
    cy.apiRequest<{ id: string }>({ method: 'GET', url: '/auth/me' })
      .its('status')
      .should('eq', 200)
  })

  it('REL 07 · cliente A baixa o relatório do cliente B e sem sessão → arquivo protegido', function () {
    cy.loginReal('cliente2')
    cy.apiRequest<{ items: Array<{ id: string }> }>({
      method: 'GET',
      url: '/relatorios/meus-relatorios?pageSize=100',
    }).then(({ body }) => {
      if (body.items.length === 0) {
        // Massa ausente: o plano manda registrar Bloqueado, não aprovar.
        cy.log('BLOQUEADO: cliente2 não tem relatório. Gere um relatório vinculado a ele.')
        this.skip()
      }
      cy.wrap(body.items.map((r) => r.id)).as('idsDeB')
    })

    cy.loginReal('cliente')
    cy.apiRequest<{ items: Array<{ id: string }> }>({
      method: 'GET',
      url: '/relatorios/meus-relatorios?pageSize=100',
    }).then(({ body: meus }) => {
      cy.get<string[]>('@idsDeB').then((idsDeB) => {
        // A lista de A nunca contém relatório de B.
        for (const id of idsDeB) {
          expect(meus.items.map((r) => r.id)).not.to.include(id)
        }

        cy.apiRequest({
          method: 'GET',
          url: `/relatorios/${idsDeB[0]}/download`,
          failOnStatusCode: false,
        })
          .its('status')
          .should('be.oneOf', NEGADO)

        // Sem sessão: nenhum cookie → 401.
        cy.clearCookies()
        cy.apiRequest({
          method: 'GET',
          url: `/relatorios/${idsDeB[0]}/download`,
          failOnStatusCode: false,
        })
          .its('status')
          .should('eq', 401)
      })
    })
  })
})

export {}
